// DATA_END

let chosenYear = 'all';
let canvasWidth = 800;
const YEAR_START = 2019, YEAR_END = 2026;
const margin = {left: 60, right: 24};
const CANVAS_HEIGHT = 1345;
const averagePlot = {top: 446, bottom: 630};
const heatTop = 1166;

function setup() {
  const holder = document.getElementById('canvas-holder');
  const selector = document.getElementById('year-select');
  if (!holder || !(selector instanceof HTMLSelectElement)) return;

  canvasWidth = holder.clientWidth;
  const canvas = createCanvas(canvasWidth, CANVAS_HEIGHT);
  canvas.parent('canvas-holder');
  canvas.elt.addEventListener('mouseleave', () => {
    hoveredHour = -1;
    hoveredHeatYear = -1;
    hoveredHeatHour = -1;
    redraw();
  });
  for (let year = YEAR_START; year <= YEAR_END; year++) {
    const option = document.createElement('option');
    option.value = String(year); option.textContent = String(year); selector.appendChild(option);
  }
  selector.addEventListener('change', () => {chosenYear = selector.value; redraw();});
  noLoop();
}

function windowResized() {
  const holder = document.getElementById('canvas-holder');
  if (!holder) return;
  const newWidth = holder.clientWidth;
  if (newWidth !== canvasWidth) {
    canvasWidth = newWidth;
    hoveredHour = -1;
    hoveredHeatYear = -1;
    hoveredHeatHour = -1;
    resizeCanvas(canvasWidth, CANVAS_HEIGHT);
    redraw();
  }
}

/** @param {string} selected */
function totals(selected) {
  const counts = [];
  for (let hour = 0; hour < 24; hour++) {
    counts.push(0);
  }
  for (const row of PHOTO_DATA.records) {
    if ((selected === 'all' || row.year === Number(selected)) && row.hour >= 0 && row.hour < 24) {
      counts[row.hour] += row.count;
    }
  }
  return counts;
}

/** @param {string} selected */
function weekdayTotals(selected) {
  const counts = [0, 0, 0, 0, 0, 0, 0];
  /** @type {Record<string, number[]>} */
  const weekdays = PHOTO_DATA.weekdaysByYear;
  for (const year in weekdays) {
    if (selected === 'all' || year === selected) {
      for (let day = 0; day < 7; day++) {
        counts[day] += weekdays[year][day];
      }
    }
  }
  return counts;
}

/** @param {string} selected */
function hourlyAverages(selected) {
  /** @type {Record<string, number>} */
  const coverage = PHOTO_DATA.daysByYear || {};
  const days = selected === 'all'
    ? Object.values(coverage).reduce((sum, count) => sum + count, 0)
    : coverage[selected] || 0;
  return {days, counts: totals(selected).map(count => days > 0 ? count / days : 0)};
}

let hoveredHour = -1;
let hoveredHeatYear = -1;
let hoveredHeatHour = -1;

function mouseMoved() {
  const right = width - margin.right;
  const hour = mouseX >= margin.left && mouseX < right
    && mouseY >= averagePlot.top && mouseY <= averagePlot.bottom
    ? Math.floor((mouseX - margin.left) / (right - margin.left) * 24) : -1;
  let heatYear = -1;
  let heatHour = -1;
  const cellWidth = (right - margin.left) / 24;
  if (mouseX >= margin.left && mouseX < right
      && mouseY >= heatTop && mouseY < heatTop + (YEAR_END - YEAR_START + 1) * 18) {
    const column = Math.floor((mouseX - margin.left) / cellWidth);
    const row = Math.floor((mouseY - heatTop) / 18);
    // Only react to the colored swatch, leaving the gaps between cells empty.
    if (mouseX < margin.left + column * cellWidth + Math.max(1, cellWidth - 1)
        && mouseY < heatTop + row * 18 + 16) {
      heatYear = YEAR_START + row;
      heatHour = column;
    }
  }
  if (hour !== hoveredHour || heatYear !== hoveredHeatYear || heatHour !== hoveredHeatHour) {
    hoveredHour = hour;
    hoveredHeatYear = heatYear;
    hoveredHeatHour = heatHour;
    redraw();
  }
}

/**
 * @param {number} left
 * @param {number} right
 */
function drawHourlyAverage(left, right) {
  const {days, counts} = hourlyAverages(chosenYear);
  const usable = right - left, band = usable / 24;
  const {top, bottom} = averagePlot;
  noStroke(); fill('#20272b'); textAlign(LEFT); textStyle(NORMAL); textSize(width < 600 ? 16 : 20);
  text('Average photos by hour', left, 376);
  fill('#707c82'); textSize(11); textLeading(16);
  const description = days > 0
    ? `Hourly total ÷ ${days.toLocaleString()} calendar ${days === 1 ? 'day' : 'days'} (Includes days with no photos.)`
    : 'No photo data covers the selected year.';
  text(description, left, 397, usable, 36);
  text('Average photos / day', left, top - 10);

  // Round the scale upward while retaining fractional daily averages.
  const rawStep = Math.max(...counts) / 4 || 0.25;
  const magnitude = 10 ** Math.floor(Math.log10(rawStep));
  const step = Math.ceil(rawStep / magnitude) * magnitude;
  const maxValue = step * 4;
  const decimals = Math.max(0, -Math.floor(Math.log10(step)));
  for (let tick = 0; tick <= 4; tick++) {
    const y = bottom - tick / 4 * (bottom - top);
    stroke('#d8ddd9'); strokeWeight(1); line(left, y, right, y);
    noStroke(); fill('#707c82'); textSize(11); textAlign(RIGHT);
    text((tick * step).toFixed(decimals), left - 9, y + 4);
  }
  stroke('#d8ddd9'); line(left, top, left, bottom);
  noStroke(); fill('#707c82'); textAlign(CENTER);
  for (let hour = 0; hour < 24; hour++) {
    if (width >= 720 || hour % 3 === 0 || hour === 23) {
      text(String(hour).padStart(2, '0'), left + (hour + .5) * band, bottom + 20);
    }
  }
  text('Hour', (left + right) / 2, bottom + 44);

  if (days > 0) {
    /** @param {number} count */
    const pointY = count => bottom - count / maxValue * (bottom - top);
    noStroke(); fill(54, 91, 140, 22); beginShape();
    vertex(left + band / 2, bottom);
    counts.forEach((count, hour) => vertex(left + (hour + .5) * band, pointY(count)));
    vertex(right - band / 2, bottom); endShape(CLOSE);
    noFill(); stroke('#365b8c'); strokeWeight(2); beginShape();
    counts.forEach((count, hour) => vertex(left + (hour + .5) * band, pointY(count)));
    endShape();
    noStroke(); fill('#365b8c');
    counts.forEach((count, hour) => circle(left + (hour + .5) * band, pointY(count), 4));

    if (hoveredHour >= 0) {
      const x = left + (hoveredHour + .5) * band, y = pointY(counts[hoveredHour]);
      stroke('#365b8c'); strokeWeight(1); line(x, top, x, bottom);
      noStroke(); fill('#365b8c'); circle(x, y, 7);
      const label = `${String(hoveredHour).padStart(2, '0')}:00 · ${counts[hoveredHour].toFixed(2)} photos/day`;
      textSize(11);
      const boxWidth = textWidth(label) + 20;
      const boxX = Math.max(left, Math.min(right - boxWidth, x - boxWidth / 2));
      const boxY = Math.max(top + 5, y - 37);
      fill('#20272b'); rect(boxX, boxY, boxWidth, 26, 4);
      fill('#ffffff'); textAlign(LEFT); text(label, boxX + 10, boxY + 17);
    }
  } else {
    noStroke(); fill('#707c82'); textAlign(CENTER); textSize(12);
    text('No data in this range', (left + right) / 2, (top + bottom) / 2);
  }
  textAlign(LEFT); strokeWeight(1);
}

/**
 * @param {number} left
 * @param {number} right
 */
function drawWeekdays(left, right) {
  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const counts = weekdayTotals(chosenYear);
  const mostPhotos = Math.max(...counts);
  const busiestDays = [];
  for (let day = 0; day < 7; day++) {
    if (mostPhotos > 0 && counts[day] === mostPhotos) {
      busiestDays.push(days[day]);
    }
  }

  noStroke();
  fill('#20272b');
  textAlign(LEFT);
  textStyle(NORMAL);
  textSize(width < 600 ? 16 : 20);
  text('Photos by day of week', left, 716);
  fill('#707c82');
  textSize(11);
  textLeading(16);
  let summary = 'No photos in the selected range.';
  const amount = mostPhotos.toLocaleString() + (mostPhotos === 1 ? ' photo' : ' photos');
  if (busiestDays.length === 1) {
    summary = 'Most photos: ' + busiestDays[0] + ' · ' + amount;
  } else if (busiestDays.length > 1) {
    summary = 'Most photos: ' + busiestDays.length + ' days tied · ' + amount + ' each';
  }
  text(summary, left, 739, right - left, 40);

  const top = 806, bottom = 996;
  const tickStep = Math.max(1, Math.ceil(mostPhotos / 4));
  const chartMax = tickStep * 4;
  text('Number of photos', left, top - 20);
  stroke('#d8ddd9');
  strokeWeight(1);
  line(left, top, left, bottom);
  for (let tick = 0; tick <= 4; tick++) {
    const count = tick * tickStep;
    const y = bottom - count / chartMax * (bottom - top);
    stroke('#d8ddd9');
    line(left, y, right, y);
    noStroke();
    fill('#707c82');
    textAlign(RIGHT);
    text(count.toLocaleString(), left - 9, y + 4);
  }

  const dayWidth = (right - left) / 7;
  for (let day = 0; day < 7; day++) {
    const barHeight = counts[day] / chartMax * (bottom - top);
    const x = left + (day + 0.5) * dayWidth;
    noStroke();
    fill('#365b8c');
    if (mostPhotos > 0 && counts[day] === mostPhotos) {
      fill('#fc537d');
    }
    rect(left + (day + 0.15) * dayWidth, bottom - barHeight, dayWidth * 0.7, barHeight, 2);

    fill('#707c82');
    textAlign(CENTER);
    textSize(width < 600 ? 9 : 11);
    text(counts[day].toLocaleString(), x, bottom - barHeight - 8);
    textSize(11);
    const label = width < 720 ? days[day].slice(0, 3) : days[day];
    text(label, x, bottom + 20);
  }
  text('Day of week', (left + right) / 2, bottom + 44);
  textAlign(LEFT);
}

function draw() {
  background('#f8f7f3');
  const counts = totals(chosenYear);
  const total = counts.reduce((a,b) => a+b, 0);
  const left = margin.left, right = width - margin.right, usable = right - left;
  noStroke(); fill('#20272b'); textAlign(LEFT); textSize(width < 600 ? 16 : 20); textStyle(NORMAL);
  text(chosenYear === 'all' ? 'Total photography by hour · all years' : `Photography by hour · ${chosenYear}`,left,38);
  fill('#707c82'); textSize(11); textLeading(16); text(`${total.toLocaleString()} photos  ·  camera-local time`,left,61);
  const top = 98, bottom = 300, maxCount = Math.max(1,...counts);
  const tickStep = Math.max(1, Math.ceil(maxCount / 4));
  const chartMax = tickStep * 4;

  noStroke(); fill('#707c82'); textSize(11);
  text('Number of photos', left, top - 12);
  stroke('#d8ddd9'); strokeWeight(1); line(left,top,left,bottom);
  for (let tick = 0; tick <= 4; tick++) {
    const count = tick * tickStep;
    const y = bottom - (count / chartMax) * (bottom - top);
    stroke('#d8ddd9'); line(left,y,right,y);
    noStroke(); fill('#707c82'); textAlign(RIGHT);
    text(count.toLocaleString(), left - 9, y + 4);
  }
  textAlign(LEFT);
  const band = usable/24;
  for(let hour=0; hour<24; hour++) {
    const bh = (counts[hour]/chartMax)*(bottom-top);
    noStroke(); fill('#365b8c');
    rect(left + hour*band + 1,bottom-bh,Math.max(1,band-3),bh,2);
  }
  noStroke();
  fill('#707c82');
  textSize(11);
  textAlign(CENTER);
  for (let hour = 0; hour < 24; hour++) {
    if (width >= 720 || hour % 3 === 0 || hour === 23) {
      text(String(hour).padStart(2, '0'), left + (hour + .5) * band, bottom + 20);
    }
  }
  text('Hour', (left + right) / 2, bottom + 44);
  textAlign(LEFT);
  drawHourlyAverage(left, right);
  drawWeekdays(left, right);
  noStroke(); fill('#20272b'); textAlign(LEFT); textStyle(NORMAL); textSize(width < 600 ? 16 : 20);
  text('Hourly amount of photos / per year',left,heatTop - 66);
  fill('#707c82'); textSize(11); textLeading(16);
  text('Color intensity represents total photos across years.',left,heatTop - 48,usable,48);
  const years = Array.from({length:YEAR_END-YEAR_START+1},(_,i)=>YEAR_START+i);
  const cellW = usable/24, cellH = 18;
  for(let yi=0;yi<years.length;yi++) {
    const year = years[yi], yc = totals(String(year)), sum = yc.reduce((a,b)=>a+b,0);
    fill('#707c82'); noStroke(); textSize(11); textAlign(RIGHT); text(year,left-10,heatTop+yi*cellH+13);
    for(let h=0;h<24;h++) {
      const share = sum > 0 ? yc[h]/sum : 0;
      const intensity = Math.min(1,share/.22);
      const low = color('#e9ecea'), high = color('#366fb9');
      noStroke(); fill(lerpColor(low, high, intensity));
      rect(left+h*cellW,heatTop+yi*cellH,Math.max(1,cellW-1),cellH-2,1);
    }
  }
  // hour labels for the graph
 textAlign(CENTER);
 fill('#707c82'); 
 textSize(11);

 for (let hour =0; hour<24; hour++){
    let label = String(hour).padStart(2, '0')+':00';
    let x = left + (hour +0.5)*cellW;
    text(label, x, heatTop + years.length * cellH + 18);
 }
 textAlign(LEFT);

  // Show the number of photos in the hovered year and hour.
  if (hoveredHeatYear >= 0 && hoveredHeatHour >= 0) {
    const count = totals(String(hoveredHeatYear))[hoveredHeatHour];
    const label = hoveredHeatYear + ' · ' + String(hoveredHeatHour).padStart(2, '0')
      + ':00 · ' + count.toLocaleString() + (count === 1 ? ' photo' : ' photos');
    const x = left + hoveredHeatHour * cellW;
    const y = heatTop + (hoveredHeatYear - YEAR_START) * cellH;

    noFill();
    stroke('#20272b');
    strokeWeight(1);
    rect(x, y, Math.max(1, cellW - 1), cellH - 2, 1);

    textSize(11);
    const boxWidth = textWidth(label) + 20;
    const boxX = Math.max(left, Math.min(right - boxWidth, x + cellW / 2 - boxWidth / 2));
    noStroke();
    fill('#20272b');
    rect(boxX, y - 34, boxWidth, 26, 4);
    fill('#ffffff');
    text(label, boxX + 10, y - 17);
  }
}
